-- generated by permdock rls generate
-- fail-closed: never target a bypass role

-- rbac scaffold (Supabase Custom Claims and RBAC)
-- authorize: database (reads user_roles on every statement)
-- the custom access token hook that writes user_role: permdock supabase hook generate
create schema if not exists "permdock";
do $$ begin
  create type "permdock"."app_role" as enum ('admin', 'member');
exception when duplicate_object then null;
end $$;
do $$ begin
  create type "permdock"."app_permission" as enum ('post.read', 'post.update', 'post.delete', 'post.publish', 'post.archive', 'post.create', 'post.list');
exception when duplicate_object then null;
end $$;

create table if not exists "permdock"."user_roles" (
  user_id uuid not null references auth.users on delete cascade,
  role "permdock"."app_role" not null,
  primary key (user_id, role)
);

alter table "permdock"."user_roles" enable row level security;
revoke all on table "permdock"."user_roles" from authenticated, anon, public;

-- permdock helpers (database: reads the membership and user_roles tables)
-- policies call them uncorrelated, so Postgres evaluates each once per statement

create schema if not exists "permdock";
revoke all on schema "permdock" from public;
grant usage on schema "permdock" to authenticated;

-- the caller's user id: the sub of request.jwt.claims, or null when it is empty or absent
create or replace function "permdock".permdock_user_id()
returns uuid
language sql
stable
set search_path = ''
as $$
  select nullif(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub',
    ''
  )::uuid
$$;
revoke execute on function "permdock".permdock_user_id() from public, anon;
grant execute on function "permdock".permdock_user_id() to authenticated;

create table if not exists "permdock".role_permissions (
  role text not null,
  permission text not null,
  grant_key text not null,
  scope text not null check (scope ~ '^[a-z][a-z0-9_]*$'),
  effect text not null default 'allow' check (effect in ('allow', 'deny')),
  primary key (role, grant_key, scope)
);
alter table "permdock".role_permissions enable row level security;
revoke all on table "permdock".role_permissions from anon, authenticated, public;

insert into "permdock".role_permissions (role, permission, grant_key, scope, effect) values
  ('admin', 'post.read', 'post.read', 'global', 'allow'),
  ('admin', 'post.update', 'post.update#1', 'global', 'allow'),
  ('admin', 'post.delete', 'post.delete', 'global', 'allow'),
  ('admin', 'post.publish', 'post.publish', 'global', 'allow'),
  ('admin', 'post.archive', 'post.archive', 'global', 'allow'),
  ('admin', 'post.create', 'post.create', 'global', 'allow'),
  ('admin', 'post.list', 'post.list', 'global', 'allow'),
  ('member', 'post.read', 'post.read', 'tenant', 'allow'),
  ('member', 'post.list', 'post.list', 'tenant', 'allow'),
  ('member', 'post.create', 'post.create', 'tenant', 'allow'),
  ('member', 'post.update', 'post.update#2', 'tenant', 'allow')
on conflict (role, grant_key, scope) do update
  set permission = excluded.permission, effect = excluded.effect;
delete from "permdock".role_permissions
where (role, grant_key, scope) not in (values
  ('admin', 'post.read', 'global'),
  ('admin', 'post.update#1', 'global'),
  ('admin', 'post.delete', 'global'),
  ('admin', 'post.publish', 'global'),
  ('admin', 'post.archive', 'global'),
  ('admin', 'post.create', 'global'),
  ('admin', 'post.list', 'global'),
  ('member', 'post.read', 'tenant'),
  ('member', 'post.list', 'tenant'),
  ('member', 'post.create', 'tenant'),
  ('member', 'post.update#2', 'tenant')
);

create or replace function "permdock".permdock_has(p_grant text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from "permdock".user_roles ur
    join "permdock".role_permissions rp on rp.role = ur.role::text
    where ur.user_id = (select "permdock".permdock_user_id())
      and rp.grant_key = p_grant
      and rp.scope = 'global'
  )
$$;
revoke execute on function "permdock".permdock_has(text) from public, anon;
grant execute on function "permdock".permdock_has(text) to authenticated;

create or replace function "permdock".permitted_tenant_ids(p_grant text)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select m."organization_id"::uuid
  from "public"."organization_members" m
  join "permdock".role_permissions rp on rp.role = m."role"::text
  where m."user_id" = (select "permdock".permdock_user_id())
    and rp.grant_key = p_grant
    and rp.scope = 'tenant'
    and (nullif(((select auth.jwt()) ->> 'tenant_id'), '') is null or m."organization_id"::text = nullif(((select auth.jwt()) ->> 'tenant_id'), ''))
$$;
revoke execute on function "permdock".permitted_tenant_ids(text) from public, anon;
grant execute on function "permdock".permitted_tenant_ids(text) to authenticated;

create or replace function "permdock".member_tenant_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select distinct m."organization_id"::uuid
  from "public"."organization_members" m
  where m."user_id" = (select "permdock".permdock_user_id())
    and m."role" is not null
$$;
revoke execute on function "permdock".member_tenant_ids() from public, anon;
grant execute on function "permdock".member_tenant_ids() to authenticated;

create or replace function "permdock".member_tenant_ids_for(p_user uuid)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select distinct m."organization_id"::uuid
  from "public"."organization_members" m
  where m."user_id" = p_user
    and m."role" is not null
$$;
revoke execute on function "permdock".member_tenant_ids_for(uuid) from public, anon, authenticated;

-- the helpers for a user the caller names: trusted SQL acting for a stored user; no client role may execute them
create or replace function "permdock".permdock_has_for(p_user uuid, p_grant text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from "permdock".user_roles ur
    join "permdock".role_permissions rp on rp.role = ur.role::text
    where ur.user_id = p_user
      and rp.grant_key = p_grant
      and rp.scope = 'global'
  )
$$;
revoke execute on function "permdock".permdock_has_for(uuid, text) from public, anon, authenticated;

create or replace function "permdock".permitted_tenant_ids_for(p_user uuid, p_grant text)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select m."organization_id"::uuid
  from "public"."organization_members" m
  join "permdock".role_permissions rp on rp.role = m."role"::text
  where m."user_id" = p_user
    and rp.grant_key = p_grant
    and rp.scope = 'tenant'
$$;
revoke execute on function "permdock".permitted_tenant_ids_for(uuid, text) from public, anon, authenticated;

-- the grant keys a permission key reaches on one scope: its unconditional allows, with p_effect 'deny' every deny, and with 'conditioned-allow' or 'conditioned-deny' the allows or denies that carry a row condition
create or replace function "permdock".grant_keys(p_permission text, p_scope text, p_effect text default 'allow')
returns setof text
language sql
stable
set search_path = ''
as $$
  select g.grant_key
  from pg_catalog.jsonb_array_elements_text(coalesce(
    '{"global":{"post.archive":{"allow":["post.archive"],"deny":[]},"post.create":{"allow":["post.create"],"deny":[]},"post.delete":{"allow":["post.delete"],"deny":[]},"post.list":{"allow":["post.list"],"deny":[]},"post.publish":{"allow":["post.publish"],"deny":[]},"post.read":{"allow":["post.read"],"deny":[]},"post.update":{"allow":["post.update#1"],"deny":[]}},"tenant":{"post.create":{"allow":["post.create"],"deny":[]},"post.list":{"allow":["post.list"],"deny":[]},"post.read":{"allow":["post.read"],"deny":[]},"post.update":{"allow":[],"deny":[],"conditioned-allow":["post.update#2"]}}}'::jsonb -> p_scope -> p_permission -> p_effect,
    '[]'::jsonb
  )) g(grant_key)
$$;
revoke execute on function "permdock".grant_keys(text, text, text) from public, anon;
grant execute on function "permdock".grant_keys(text, text, text) to authenticated;

-- the helpers by permission key: unconditional allows minus any deny
create or replace function "permdock".permdock_has_permission(p_permission text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from "permdock".grant_keys(p_permission, 'global') g(grant_key) where "permdock".permdock_has(g.grant_key))
    and not exists (select 1 from "permdock".grant_keys(p_permission, 'global', 'deny') g(grant_key) where "permdock".permdock_has(g.grant_key))
$$;
revoke execute on function "permdock".permdock_has_permission(text) from public, anon;
grant execute on function "permdock".permdock_has_permission(text) to authenticated;

create or replace function "permdock".permitted_tenant_ids_by_permission(p_permission text)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select a.id
  from "permdock".grant_keys(p_permission, 'tenant') g(grant_key)
  cross join lateral "permdock".permitted_tenant_ids(g.grant_key) a(id)
  except
  select d.id
  from "permdock".grant_keys(p_permission, 'tenant', 'deny') g(grant_key)
  cross join lateral "permdock".permitted_tenant_ids(g.grant_key) d(id)
$$;
revoke execute on function "permdock".permitted_tenant_ids_by_permission(text) from public, anon;
grant execute on function "permdock".permitted_tenant_ids_by_permission(text) to authenticated;

-- with p_conditioned true, also the instances a conditioned allow reaches, minus only unconditional denies: the caller applies the row condition
create or replace function "permdock".permitted_tenant_ids_by_permission(p_permission text, p_conditioned boolean)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select a.id
  from (
    select g.grant_key from "permdock".grant_keys(p_permission, 'tenant') g(grant_key)
    union all
    select g.grant_key from "permdock".grant_keys(p_permission, 'tenant', 'conditioned-allow') g(grant_key)
    where p_conditioned
  ) g
  cross join lateral "permdock".permitted_tenant_ids(g.grant_key) a(id)
  except
  select d.id
  from (
    select g.grant_key from "permdock".grant_keys(p_permission, 'tenant', 'deny') g(grant_key)
    except
    select g.grant_key from "permdock".grant_keys(p_permission, 'tenant', 'conditioned-deny') g(grant_key)
    where p_conditioned
  ) g
  cross join lateral "permdock".permitted_tenant_ids(g.grant_key) d(id)
$$;
revoke execute on function "permdock".permitted_tenant_ids_by_permission(text, boolean) from public, anon;
grant execute on function "permdock".permitted_tenant_ids_by_permission(text, boolean) to authenticated;

-- the same for a user the caller names; no client role may execute them
create or replace function "permdock".permdock_has_permission_for(p_user uuid, p_permission text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from "permdock".grant_keys(p_permission, 'global') g(grant_key) where "permdock".permdock_has_for(p_user, g.grant_key))
    and not exists (select 1 from "permdock".grant_keys(p_permission, 'global', 'deny') g(grant_key) where "permdock".permdock_has_for(p_user, g.grant_key))
$$;
revoke execute on function "permdock".permdock_has_permission_for(uuid, text) from public, anon, authenticated;

create or replace function "permdock".permitted_tenant_ids_by_permission_for(p_user uuid, p_permission text)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
